// UI strings for every language the site speaks — no DOM, no fetch,
// unit-tested via node --test. German is the default; the picker lists LANGS.
// The legal pages (Impressum, Datenschutz) stay German-only by design. Values may
// carry trusted markup (<b>, <a>, <code>) — they are constants from this file,
// never user input; anything interpolated into {tokens} must be escaped by the
// caller.

// At least one official language of every swept country, plus English.
// de/en/da came first; nl, fr, it, cs, pl and sv arrived with the UK and
// France; the 22 from bs to uk arrived with the Europe-complete ring. Order is
// the order the picker lists them in: German first because the site is
// German-first, then each arrival group by endonym.
// Deliberately absent, all on the Romansh precedent (no monolingual readers —
// every speaker reads another UI language): Romansh itself, Luxembourgish
// (fr/de), Maltese and Irish (en), Montenegrin (mutually intelligible with
// sr/hr/bs), and Turkish for Cyprus (the swept republic's public signage
// pairs el with en).
export const LANGS = ["de", "en", "da", "nl", "fr", "it", "cs", "pl", "sv",
                      "bs", "ca", "et", "es", "hr", "is", "lv", "lt", "hu",
                      "no", "pt", "ro", "sq", "sk", "sl", "fi", "el", "be",
                      "bg", "mk", "sr", "uk", "ja"];
export const DEFAULT_LANG = "de";

// Thousands separators differ per language and the strip is full of counts.
// Every region here is the language's European home: the site's English is
// British ("colour", "26 July 2026"), and en-US was the one entry that said
// otherwise. It makes no difference to a number — both group with "," — but
// the methods pages format a date from the same tag, where en-US would write
// "Jul 26, 2026" under British prose.
export const NUMBER_LOCALE = {
  de: "de-DE", en: "en-GB", da: "da-DK", nl: "nl-NL", fr: "fr-FR",
  it: "it-IT", cs: "cs-CZ", pl: "pl-PL", sv: "sv-SE",
  bs: "bs-BA", ca: "ca-AD", et: "et-EE", es: "es-ES", hr: "hr-HR",
  is: "is-IS", lv: "lv-LV", lt: "lt-LT", hu: "hu-HU", no: "nb-NO",
  pt: "pt-PT", ro: "ro-RO", sq: "sq-AL", sk: "sk-SK", sl: "sl-SI",
  fi: "fi-FI", el: "el-GR", be: "be-BY", bg: "bg-BG", mk: "mk-MK",
  sr: "sr-RS", uk: "uk-UA", ja: "ja-JP",
};

// Browser tags that name one of our languages under a different code. Norwegian
// browsers report Bokmål/Nynorsk as "nb"/"nn", never the site's macrolanguage
// code "no" — without the alias no Norwegian visitor would ever be detected.
const LANG_ALIASES = { nb: "no", nn: "no" };

// Query param beats stored choice beats browser language beats default — a
// shared ?lang=en link should win over the recipient's remembered preference.
//
// Every language is auto-detected now, not just Danish. The old rule existed
// because the site spoke three languages and two of them were wrong for most
// visitors; with thirty-two, a Czech reader arriving on a German page is the
// worse default. The cost is real and was the reason for the old rule: a German
// reader running an English browser now lands on English. They can switch,
// and the choice is remembered — `stored` is checked before the browser, so
// one click settles it permanently.
//
// `nav` accepts navigator.languages (preferred — it is ordered by preference)
// or a single navigator.language string. Region subtags are ignored: "en-GB",
// "de-AT" and "fr-CH" all match their base language, which is what the tag
// means. An unsupported language falls through to the next entry rather than
// ending the search, so a ["ga", "en"] browser gets English, not German.
export function pickLang(query, stored, nav) {
  if (LANGS.includes(query)) return query;
  if (LANGS.includes(stored)) return stored;
  const prefs = Array.isArray(nav) ? nav : [nav];
  for (const tag of prefs) {
    let base = String(tag ?? "").toLowerCase().split("-")[0];
    base = LANG_ALIASES[base] ?? base;
    if (LANGS.includes(base)) return base;
  }
  return DEFAULT_LANG;
}

// The map serves all its languages from one URL, so each language needs a
// distinct address for search engines to index it separately: German owns the
// bare URL, the others hang off the same ?lang= param pickLang() already
// honours. Keep in sync with index.html's hreflang tags and sitemap.xml.
export function langUrl(lang, base = "https://papamap.de/") {
  return lang === DEFAULT_LANG ? base : `${base}?lang=${lang}`;
}

// The canonical is the address's own language, never the one the page drew.
// A reader whose browser speaks English sees English at the bare URL, and the
// canonical there must still say the bare URL: pointing it at ?lang=en made
// Googlebot (which reports en-US) read / as a duplicate of ?lang=en, fold the
// German and English views into one entry, and drop it from English-language
// results for "papamap" (2026-09-25).
export function canonicalUrl(query) {
  return langUrl(LANGS.includes(query) ? query : DEFAULT_LANG);
}

// A crawler gets what the address says and nothing else: German at the bare
// URL, as index.html's hreflang declares it, whatever language its renderer
// reports. Every reader with no preference of their own sees the same page.
// Crawlers name themselves "Somebot/1.0"; a bare "bot" would also catch phones
// whose model ends in it (a CUBOT X30 puts "CUBOT X30" in its user agent).
const CRAWLER = /bot\/|crawl|spider|slurp|Google-InspectionTool/i;

export function isCrawler(ua) {
  return CRAWLER.test(String(ua ?? ""));
}

// Tiny {token} interpolation; unknown tokens stay literal so a missing var is
// visible instead of silently vanishing.
export function fmt(template, vars = {}) {
  return String(template).replace(/\{(\w+)\}/g,
    (m, k) => (k in vars ? String(vars[k]) : m));
}

